function formModal(d){const obj=modal.id?d[tab].find(x=>x.id===modal.id)||{}:{};const customers=d.customers.map(c=>`<option value="${esc(c.id)}" ${obj.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('');const defs={expenses:[['title','Expense description','text',true],['category','Trade category','category',true],['amount','Amount (€)','number',true],['date','Date','date',true]],customers:[['name','Customer name','text',true],['phone','Phone','tel'],['email','Email','email'],['address','Address','text']],quotes:[['customerId','Customer','customer',true],['title','Description','text',true],['category','Trade category','category',true],['amount','Estimated value (€)','number',true],['status','Status','select:Draft,Sent,Accepted,Declined'],['sentDate','Date sent','date']],jobs:[['customerId','Customer','customer',true],['title','Job description','text',true],['category','Trade category','category',true],['status','Status','select:Planned,In Progress,Completed'],['date','Scheduled date','date']],tasks:[['title','Task','text',true],['customerId','Customer','customer'],['due','Due date','date',true],['status','Status','select:Open,Done']]}[tab];return `<div class="dialog"><form class="modal" id="recordForm"><div class="modalhead"><h2>${modal.id?'Edit':'New'} ${tab.slice(0,-1)}</h2><button class="btn secondary small" type="button" data-action="close">✕</button></div><div class="formgrid">${defs.map(([key,label,type,required])=>`<label class="field">${label}${type==='category'?`<select class="input" name="${key}">${prefs.categories.map(v=>`<option value="${esc(v)}" ${obj[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='customer'?`<select class="input" name="${key}" ${required?'required':''}><option value="">Choose customer</option>${customers}</select>`:type.startsWith('select:')?`<select class="input" name="${key}">${type.slice(7).split(',').map(v=>`<option ${obj[key]===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input class="input" name="${key}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} value="${esc(obj[key]??(type==='date'&&key==='due'?today():''))}">`}</label>`).join('')}</div><div class="actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn" type="submit">Save record</button></div></form></div>`}
async function saveForm(form){const f=Object.fromEntries(new FormData(form));if(tab==='customers'){f.email=f.email.trim().toLowerCase();const existing=(await all('customers')).find(c=>c.id!==modal.id&&((f.email&&c.email===f.email)||(f.phone&&c.phone===f.phone)));if(existing&&!confirm('A customer already has this email or phone. Save anyway?'))return}const id=modal.id||uid(),old=modal.id?await get(tab,id):{};await put(tab,{...old,...f,id,updatedAt:new Date().toISOString()});await event(`${modal.id?'Updated':'Created'} ${tab.slice(0,-1)}: ${f.name||f.title}`);if(tab==='quotes'&&f.status==='Sent'&&old.status!=='Sent'){const tasks=await all('tasks');if(!tasks.some(t=>t.quoteId===id)){await put('tasks',{id:uid(),title:`Follow up quote: ${f.title}`,customerId:f.customerId,due:new Date(Date.now()+3*86400000).toISOString().slice(0,10),status:'Open',quoteId:id});await event('Created quote follow-up task')}}modal=null;query='';notify('Record saved')}
async function exportData(){const data={format:'tradeflow-lite',version:4,exportedAt:new Date().toISOString(),stores:Object.fromEntries(await Promise.all(STORES.map(async s=>[s,await all(s)])))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`tradeflow-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function restore(file){let data;try{data=JSON.parse(await file.text());if(data.format!=='tradeflow-lite'||![1,2,3,4].includes(data.version)||!data.stores||!STORES.every(s=>Array.isArray(data.stores[s]||((data.version<4||s==='pins')?[]:null))&&(data.stores[s]||[]).every(x=>x&&typeof x.id==='string')))throw Error('Invalid backup');if(!confirm('Replace ALL existing local records with this backup? This cannot be undone.'))return;const t=db.transaction(STORES,'readwrite');for(const s of STORES){const st=t.objectStore(s);st.clear();for(const item of (data.stores[s]||[]))st.put(item)}await new Promise((resolve,reject)=>{t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)});notify('Backup restored')}catch(e){alert(`Restore failed: ${e.message}`)}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-tab],[data-action],[data-edit],[data-delete],[data-convert]');if(!el)return;if(el.dataset.action==='settingsPanel'){showSettingsPanel(el.dataset.panel);return}if(el.dataset.action==='moreSettings'||el.dataset.action==='moreHelp'){const target=document.getElementById(el.dataset.action==='moreSettings'?'tfMoreSettings':'tfMoreHelp');const other=document.getElementById(el.dataset.action==='moreSettings'?'tfMoreHelp':'tfMoreSettings');if(target){const opening=target.hidden;target.hidden=!opening;if(other)other.hidden=true;if(opening)target.scrollIntoView({behavior:'smooth',block:'nearest'})}return}if(el.dataset.action==='mapFilters'){const controls=document.getElementById('tfMapControls');if(controls)controls.hidden=!controls.hidden;return}if(el.dataset.action==='mapMode'){prefs.mapMode=el.dataset.mode;await put('settings',{id:'business',...prefs});const d=Object.fromEntries(await Promise.all(STORES.map(async store=>[store,await all(store)])));initializeMap(d);return}if(el.dataset.action==='mapSearch'){searchMapAddress();return}if(el.dataset.action==='mapHome'){setMapHome();return}if(el.dataset.action==='mapPinDelete'){if(confirm('Delete this saved map pin?')){await del('pins',el.dataset.id);render()}return}if(el.dataset.action==='mapPinView'){focusMapPin(el.dataset.id);return}if(el.dataset.action==='opportunityReviewClose'){opportunityImportDraft=null;render();return}if(el.dataset.action==='opportunityReviewTab'){opportunityImportTab=el.dataset.filter;render();return}if(el.dataset.action==='opportunityReviewSave'){await saveOpportunityImportDraft();return}if(el.dataset.action==='opportunityMapAll'){mapLastView=null;tab='map';render();return}if(el.dataset.action==='opportunityMapRemaining'){await locateOpportunityBatch(await all('opportunities'));return}if(el.dataset.action==='opportunityLocate'){const r=await get('opportunities',el.dataset.id);if(!r)return;const address=[r.address,r.city,r.region].filter(Boolean).join(', ')||[r.project_name,r.city,r.region].filter(Boolean).join(', ');if(!address)return alert('No address available for this record.');if(!confirm('Look up the location for '+r.project_name+'? Internet is required. Please verify the result on the map.'))return;try{const result=await mapNominatim('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(address));if(!result.length)throw Error('No matching address');const lat=Number(result[0].lat),lon=Number(result[0].lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))throw Error('Invalid location');r.latitude=lat;r.longitude=lon;r.map_enabled=true;r.map_address_result=String(result[0].display_name||'');r.map_location_status='needs_review';await put('opportunities',r);mapLastView={center:[lon,lat],zoom:14};tab='map';await render();notify('Approximate location plotted — verify the pin before relying on it.')}catch(err){alert('Could not locate record: '+err.message)}return}if(el.dataset.action==='opportunityMapFilters'){opportunityFilter=opportunityFilter==='unmapped'?'all':'unmapped';opportunityDetailId=null;render();return}if(el.dataset.action==='opportunityImportToggle'){const box=document.getElementById('opportunityImportTools');if(box)box.hidden=!box.hidden;return}if(el.dataset.action==='opportunityFilter'){opportunityFilter=el.dataset.filter;opportunityDetailId=null;render();return}if(el.dataset.action==='opportunityDetail'){opportunityDetailId=el.dataset.id;await render();document.querySelector('.tf-op-detail')?.scrollIntoView({block:'start',behavior:'auto'});return}if(el.dataset.action==='opportunityClose'){opportunityDetailId=null;render();return}if(el.dataset.action==='opportunityMap'){const r=await get('opportunities',el.dataset.id);if(r&&opportunityMapped(r)){mapLastView={center:[r.longitude,r.latitude],zoom:15};tab='map';render()}return}if(el.dataset.action==='importOpportunities'){document.getElementById('opportunityFile')?.click();return}if(el.dataset.action==='exportOpportunities'){exportOpportunities();return}if(el.dataset.action==='opportunityStatus'){const r=await get('opportunities',el.dataset.id);if(r){r.status=el.dataset.status;await put('opportunities',r);notify('Opportunity updated')}return}if(el.dataset.tab){tab=el.dataset.tab;query='';modal=null;render()}else if(el.dataset.action==='new'){if(['quotes','jobs','tasks'].includes(tab)&&(await all('customers')).length===0){alert('Create a customer first.');tab='customers';render();return}modal={};render()}else if(el.dataset.action==='close'){modal=null;render()}else if(el.dataset.action==='export')exportData();else if(el.dataset.edit){modal={id:el.dataset.edit};render()}else if(el.dataset.delete){if(!confirm('Delete this record? This cannot be undone.'))return;const id=el.dataset.delete;if(tab==='customers'){const refs=await Promise.all(['quotes','jobs','tasks'].map(all));if(refs.some(a=>a.some(x=>x.customerId===id))){alert('This customer has linked records. Remove or reassign those first.');return}}await del(tab,id);await event(`Deleted ${tab.slice(0,-1)}`);notify('Record deleted')}else if(el.dataset.convert){const q=await get('quotes',el.dataset.convert);if(q?.status!=='Accepted')return;const jobs=await all('jobs');if(jobs.some(j=>j.quoteId===q.id))return;await put('jobs',{id:uid(),quoteId:q.id,customerId:q.customerId,title:q.title,category:q.category||'Other',status:'Planned',date:''});await event(`Created job from accepted quotation: ${q.title}`);notify('Job created')}});
document.addEventListener('change',e=>{if(e.target.id==='tfImportMapChoice'&&opportunityImportDraft)opportunityImportDraft.mapLocations=e.target.checked});
document.addEventListener('submit',async e=>{if(e.target.id==='settingsForm'){e.preventDefault();const f=new FormData(e.target),company=String(f.get('company')||'').trim(),address=String(f.get('businessAddress')||'').trim();if(!company)return alert('Enter a business name');let home={};if(address!==String(prefs.businessAddress||'')){if(address){try{const results=await mapNominatim('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&q='+encodeURIComponent(address));if(!results.length||!Number.isFinite(Number(results[0].lat))||!Number.isFinite(Number(results[0].lon)))throw Error('Address not found');home={homeLat:Number(results[0].lat),homeLon:Number(results[0].lon)}}catch(err){alert('Address could not be verified. No changes saved. '+err.message);return}}else home={homeLat:'',homeLon:''}}prefs={...prefs,company,contactName:String(f.get('contactName')||'').trim(),contactEmail:String(f.get('contactEmail')||'').trim(),contactPhone:String(f.get('contactPhone')||'').trim(),businessAddress:address,...home};await put('settings',{id:'business',...prefs});if(Object.keys(home).length)mapLastView=null;notify('Business profile saved');return}if(e.target.id==='appearanceForm'){e.preventDefault();prefs.accent=String(new FormData(e.target).get('accent')||'#00dce8');await put('settings',{id:'business',...prefs});notify('Appearance saved');return}if(e.target.id==='opportunityWorkflowForm'){e.preventDefault();const id=e.target.dataset.id;const record=await get('opportunities',id);if(!record)return;const fd=new FormData(e.target);record.status=String(fd.get('status')||'New');record.followup_date=String(fd.get('followup_date')||'');record.sales_notes=String(fd.get('sales_notes')||'').slice(0,4000);record.workflow_updated_at=new Date().toISOString();await put('opportunities',record);opportunityDetailId=null;await render();notify('Opportunity workflow saved');return}if(e.target.id==='recordForm'){e.preventDefault();saveForm(e.target).catch(err=>alert(err.message))}});document.addEventListener('input',e=>{if(e.target.id==='mapAddress'){showLocalMapSuggestions(e.target.value);return}if(e.target.id==='opportunitySearch'){opSearch=e.target.value;render().then(()=>{const i=$('#opportunitySearch');i?.focus();i?.setSelectionRange(opSearch.length,opSearch.length)});return}if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render().then(()=>{const i=$('#search');i?.focus();i?.setSelectionRange(pos,pos)})}});document.addEventListener('change',e=>{if(e.target.matches('[data-import-id]')&&opportunityImportDraft){if(e.target.checked)opportunityImportDraft.selected.add(e.target.dataset.importId);else opportunityImportDraft.selected.delete(e.target.dataset.importId);const btn=document.querySelector('.tf-import-save');if(btn){btn.textContent='Save '+opportunityImportDraft.selected.size+' Records';btn.disabled=!opportunityImportDraft.selected.size}}});
document.addEventListener('change',e=>{if(e.target.id==='restoreFile'&&e.target.files[0])restore(e.target.files[0]);if(e.target.id==='opportunityFile'&&e.target.files[0])importOpportunities(e.target.files[0]).catch(err=>alert(err.message))});

let opSearch='';
const opFields=['record_id','source_record_id','project_name','trade','opportunity_type','project_description','city','region','latitude','longitude','source_url','source_date','discovered_at','verified_at','evidence_status','status','organization_name','contact_url','evidence_notes'];
function parseCSV(text){if(text.charCodeAt(0)===0xFEFF)text=text.slice(1);const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('Unclosed CSV quotation mark');if(field||row.length){row.push(field);rows.push(row)}return rows}
function csvCell(v){const t=String(v??'');return /[",\r\n]/.test(t)?'"'+t.replace(/"/g,'""')+'"':t}
function downloadFile(filename,content,mime){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:mime}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function exportOpportunities(){const data=await all('opportunities');downloadFile('tradeflow-opportunities-'+today()+'.csv',[opFields.join(','),...data.map(r=>opFields.map(f=>csvCell(r[f])).join(','))].join('\r\n'),'text/csv')}
function convertE06Audit(rows){const headers=rows[0].map(x=>x.trim().toLowerCase());const col=(row,name)=>row[headers.indexOf(name)]||'';const converted=[opFields];for(const row of rows.slice(1)){const qc=col(row,'qc_decision').toUpperCase(),kind=col(row,'submitted_classification').toLowerCase(),location=col(row,'location'),id=col(row,'record_id');const record={record_id:id,source_record_id:id,project_name:col(row,'entity_or_project'),trade:'Electrical',opportunity_type:kind.includes('potential')?'potential_opportunity':kind.includes('business')?'business_prospect':'project_signal',project_description:location+'; '+col(row,'reviewer_notes'),city:location,region:'Texas',latitude:'',longitude:'',source_url:col(row,'original_source_url'),source_date:col(row,'source_date')||col(row,'research_date'),discovered_at:col(row,'research_date'),verified_at:col(row,'research_date'),evidence_status:qc==='UNRESOLVED'?'unresolved':'source_supported',status:'New',organization_name:col(row,'entity_or_project'),contact_url:'',evidence_notes:'E06 QC: '+qc+'; '+col(row,'source_verification')};converted.push(opFields.map(f=>record[f]||''))}return converted}
async function importOpportunities(file){if(file.size>5*1024*1024)throw Error('File exceeds 5 MB');const rows=parseCSV(await file.text());if(rows.length<2)throw Error('CSV must contain a header and at least one record');if(rows.length>5001)throw Error('Import a maximum of 5,000 records at a time');if(rows[0].map(v=>v.trim().toLowerCase()).includes('qc_decision')){const converted=convertE06Audit(rows);rows.splice(0,rows.length,...converted)}const headers=rows.shift().map(v=>v.trim().toLowerCase());for(const f of ['record_id','project_name','opportunity_type','source_url'])if(!headers.includes(f))throw Error('Missing required column: '+f);const allowedTypes=['project_signal','potential_opportunity','verified_request','business_prospect'];const existing=await all('opportunities'),ids=new Set(existing.map(x=>x.id)),sources=new Set(existing.filter(x=>x.source_record_id).map(x=>x.source_url+'|'+x.source_record_id));let added=0,duplicates=0,rejected=0;const staged=[];const validUrl=u=>{try{const v=new URL(u);return ['https:','http:'].includes(v.protocol)}catch{return false}};
for(const cells of rows){if(cells.length!==headers.length){rejected++;continue}const raw=Object.fromEntries(headers.map((h,i)=>[h,(cells[i]||'').trim()]));const id=raw.record_id,lat=raw.latitude?Number(raw.latitude):null,lon=raw.longitude?Number(raw.longitude):null;if(!id||id.length>150||!raw.project_name||!['verified','source_supported','unresolved'].includes(raw.evidence_status)||!allowedTypes.includes(raw.opportunity_type)||!validUrl(raw.source_url)||!raw.source_url.startsWith('https://')||!raw.source_date||!raw.verified_at||(raw.latitude&&(!Number.isFinite(lat)||Math.abs(lat)>90))||(raw.longitude&&(!Number.isFinite(lon)||Math.abs(lon)>180))||(raw.latitude&&!raw.longitude)||(!raw.latitude&&raw.longitude)){rejected++;continue}const sourceKey=raw.source_url+'|'+raw.source_record_id;if(ids.has(id)||(raw.source_record_id&&sources.has(sourceKey))){duplicates++;continue}ids.add(id);if(raw.source_record_id)sources.add(sourceKey);staged.push({...Object.fromEntries(opFields.map(f=>[f,raw[f]||''])),id,latitude:lat,longitude:lon,trade:raw.trade||'Electrical',evidence_status:raw.evidence_status||'unreviewed',status:'New',imported_at:new Date().toISOString()})}
if(!staged.length){alert('No eligible new records. Duplicates: '+duplicates+'; invalid: '+rejected);return}
opportunityImportDraft={records:staged,duplicates,rejected,selected:new Set(staged.map(x=>x.id)),mapLocations:true};opportunityImportTab='all';await render();return}
let opportunityImportDraft=null,opportunityImportTab='all';
function opportunityReviewModal(){
const draft=opportunityImportDraft;if(!draft)return '';
const records=draft.records.filter(x=>opportunityImportTab==='all'||(opportunityImportTab==='review'?x.evidence_status!=='verified':['Saved','Contacted','Interested','Quoted','Won','Lost'].includes(x.status)));
const selected=draft.selected.size;
return `<div class="tf-import-backdrop"><section class="tf-import-dialog" role="dialog" aria-modal="true" aria-label="Review import"><header class="tf-import-head"><div class="tf-import-symbol">◇</div><div><h2>REVIEW IMPORT</h2><p>Check and confirm extracted records.</p></div><button type="button" data-action="opportunityReviewClose" aria-label="Close review">×</button></header>
<div class="tf-import-tabs"><button class="${opportunityImportTab==='all'?'active':''}" data-action="opportunityReviewTab" data-filter="all">All (${draft.records.length})</button><button class="${opportunityImportTab==='review'?'active':''}" data-action="opportunityReviewTab" data-filter="review">Needs review (${draft.records.filter(x=>x.evidence_status!=='verified').length})</button><button class="${opportunityImportTab==='saved'?'active':''}" data-action="opportunityReviewTab" data-filter="saved">Pipeline (${draft.records.filter(x=>['Saved','Contacted','Interested','Quoted','Won','Lost'].includes(x.status)).length})</button></div>
<div class="tf-import-tablewrap"><table class="tf-import-table"><thead><tr><th>Name</th><th>Type</th><th>Address</th><th>Evidence</th><th>Include</th></tr></thead><tbody>${records.map(x=>`<tr><td><strong>${esc(x.project_name)}</strong></td><td>${esc(x.opportunity_type.replaceAll('_',' '))}</td><td>${esc([x.city,x.region].filter(Boolean).join(', ')||'Not provided')}</td><td><span class="tf-import-evidence ${x.evidence_status==='verified'?'ok':'warn'}">${x.evidence_status==='verified'?'✓':'⚠'} ${esc(x.evidence_status)}</span></td><td><input type="checkbox" data-import-id="${esc(x.id)}" ${draft.selected.has(x.id)?'checked':''} aria-label="Include ${esc(x.project_name)}"></td></tr>`).join('')}</tbody></table></div><p class="tf-import-note">${draft.duplicates} duplicates and ${draft.rejected} invalid rows excluded. Evidence status is not a sales-confidence score.</p>
<label class="tf-import-mapchoice"><input type="checkbox" id="tfImportMapChoice" ${draft.mapLocations?'checked':''}><span><strong>Map imported locations</strong><small>${draft.records.filter(x=>draft.selected.has(x.id)&&opportunityHasLocation(x)).length} selected records have coordinates. Others stay in Not mapped.</small></span></label><div class="tf-import-actions"><button class="tf-import-edit" type="button" data-action="opportunityReviewClose">Cancel</button><button class="tf-import-save" type="button" data-action="opportunityReviewSave" ${selected?'':'disabled'}>Save ${selected} Records</button></div></section></div>`;
}
async function saveOpportunityImportDraft(){const draft=opportunityImportDraft;if(!draft)return;const selected=draft.records.filter(x=>draft.selected.has(x.id));if(!selected.length)return;const transaction=db.transaction('opportunities','readwrite');for(const r of selected)transaction.objectStore('opportunities').put({...r,map_enabled:draft.mapLocations&&opportunityHasLocation(r)});await new Promise((resolve,reject)=>{transaction.oncomplete=resolve;transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error)});opportunityImportDraft=null;notify('Imported '+selected.length+' records');render()}
const opportunityHasLocation=x=>typeof x.latitude==='number'&&typeof x.longitude==='number'&&Number.isFinite(x.latitude)&&Number.isFinite(x.longitude)&&Math.abs(x.latitude)<=90&&Math.abs(x.longitude)<=180;
const opportunityMapped=x=>opportunityHasLocation(x)&&x.map_enabled!==false;
const opportunityStage=x=>{const status=String(x.status||'New').toLowerCase().trim();if(['won','completed','finished','job won'].includes(status))return 'won';if(['lost','rejected'].includes(status))return 'lost';if(['in progress','active','interested','working'].includes(status))return 'active';if(['follow-up','followup','follow up'].includes(status)||(x.followup_date&&x.followup_date<=new Date().toISOString().slice(0,10)&&!['quoted','won','lost'].includes(status)))return 'followup';if(['quoted','quote sent','proposal'].includes(status))return 'quoted';if(['contacted','replied'].includes(status))return 'contacted';if(status==='saved')return 'saved';return 'new'};
const opportunityStageName=x=>({won:'Won / job',quoted:'Quoted',active:'In progress',contacted:'Contacted',followup:'Follow-up',saved:'Saved',lost:'Lost',new:'New lead'})[opportunityStage(x)];
/* One shared SVG vocabulary for opportunity cards and map pins. */
const opportunityStageSvg=x=>{const stage=opportunityStage(x),path=({
 won:'<circle cx="12" cy="12" r="9"/><path d="m7.5 12 3 3 6-6"/>',
 quoted:'<path d="M7 3.5h8l4 4V20H7z"/><path d="M15 3.5v4h4M10 12h6M10 15h4"/><path d="m14 18 1.4 1.4L18 17"/>',
 active:'<path d="M3 17h18v3H3zM5 16a7 7 0 0 1 14 0M10 8V5h4v3"/>',
 contacted:'<path d="M4 5h16v12H8l-4 4zM8 9h8M8 13h5"/>',
 followup:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
 saved:'<path d="M6 3h12v18l-6-4-6 4z"/>',
 lost:'<circle cx="12" cy="12" r="9"/><path d="m9 9 6 6m0-6-6 6"/>',
 new:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1.5"/>'
})[stage];return '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+path+'</svg>'};
let opportunityDetailId=null,opportunityFilter='all';

function opportunityAddressVariants(r){
 const street=String(r.address||'').trim(),city=String(r.city||'').trim(),region=String(r.region||'').trim(),zip=String(r.postal_code||r.zip||r.zip_code||'').trim();
 const parts=[street,city,region,zip].filter(Boolean);
 const variants=[parts.join(', ')];
 if(street){
  const normalized=street.replace(/\\s+/g,' ').replace(/,?\\s*(?:United States|USA)\\s*$/i,'').trim();
  variants.push([normalized,city,region].filter(Boolean).join(', '));
  const trailing=normalized.match(/^(.+?)\\s+(\\d+[A-Za-z]?)$/);
  if(trailing)variants.push([trailing[2]+' '+trailing[1],city,region,zip].filter(Boolean).join(', '));
  const leading=normalized.match(/^(\\d+[A-Za-z]?)\\s+(.+)$/);
  if(leading)variants.push([leading[2]+' '+leading[1],city,region,zip].filter(Boolean).join(', '));
 }
 if(!street&&r.project_name)variants.push([r.project_name,city,region].filter(Boolean).join(', '));
 return [...new Set(variants.map(x=>x.trim()).filter(Boolean))].slice(0,3);
}
function opportunityLocationPlausible(hit,r){
 const name=String(hit.display_name||'').toLowerCase();
 const city=String(r.city||'').trim().toLowerCase();
 const zip=String(r.postal_code||r.zip||r.zip_code||'').trim();
 if(zip&&/^[0-9]{5}(?:-[0-9]{4})?$/.test(zip)&&name.includes(zip.slice(0,5)))return true;
 if(city&&name.includes(city))return true;
 if(!city&&!zip)return true;
 return false;
}
let opportunityMappingRunning=false;
async function locateOpportunityBatch(records){
 if(opportunityMappingRunning)return alert('Address mapping is already running.');
 if(!navigator.onLine)return alert('Internet access is required for address lookup.');
 const pending=records.filter(x=>!opportunityMapped(x)&&opportunityAddressVariants(x).length&&x.map_location_status!=='unresolved');
 const retry=records.filter(x=>!opportunityMapped(x)&&x.map_location_status==='unresolved'&&opportunityAddressVariants(x).length);
 const queue=[...pending,...retry];
 if(!queue.length)return alert('No unmapped records with usable location information remain.');
 const max=Math.min(20,queue.length);
 if(!confirm('Search '+max+' addresses ('+pending.length+' new, '+retry.length+' previous no-matches)? Online lookup is rate-limited and results need verification.'))return;
 opportunityMappingRunning=true;
 let located=0,unmatched=0,errors=0,processed=0,stopped=false;
 const progress=document.getElementById('tfMapProgress');
 if(progress){progress.hidden=false;progress.textContent='Mapping 0 / '+max+'…'}
 const cache=new Map();
 try{
  for(const record of queue.slice(0,max)){
   try{
    let hit=null,plausible=false;
    for(const address of opportunityAddressVariants(record)){
     const key=address.toLowerCase().replace(/\\s+/g,' ');
     let results;
     if(cache.has(key))results=cache.get(key);
     else{results=await mapNominatim('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=3&q='+encodeURIComponent(address));cache.set(key,results)}
     const candidates=Array.isArray(results)?results:[];
     const candidate=candidates.find(x=>opportunityLocationPlausible(x,record));
     if(candidate){hit=candidate;plausible=true;break}
     if(!hit&&candidates.length)hit=candidates[0];
    }
    const lat=Number(hit?.lat),lon=Number(hit?.lon);
    if(!hit||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||!plausible){
     record.map_location_status='unresolved';record.map_error=hit?'Found only a location outside the expected city or ZIP':'No matching address';unmatched++;
    }else{
     record.latitude=lat;record.longitude=lon;record.map_enabled=true;
     record.map_location_status='needs_review';record.map_address_result=String(hit.display_name||'');
     delete record.map_error;located++;
    }
    await put('opportunities',record);
   }catch(err){
    errors++;
    if(/429|403|503|rate|limit/i.test(String(err.message||''))){stopped=true;break}
    record.map_location_status='lookup_error';record.map_error=String(err.message||'Lookup failed').slice(0,160);
    await put('opportunities',record);
   }
   processed++;
   if(progress)progress.textContent='Mapping '+processed+' / '+max+' · '+located+' located · '+unmatched+' unmatched';
  }
 }finally{opportunityMappingRunning=false}
 mapLastView=null;await render();
 alert(located+' mapped for review, '+unmatched+' unmatched, '+errors+' errors. '+(stopped?'The geocoding provider paused requests; retry later. ':'')+'Use Map remaining to continue.');
}

