let homePeriod='1M';
function buildHomeRevenueChart(d,period){
const series=getFinanceSeries(d,period),raw=series.points;
const count=period==='1W'?7:period==='1M'?10:12;
const groupSize=Math.max(1,Math.ceil(raw.length/count));
const groups=[];for(let i=0;i<raw.length;i+=groupSize)groups.push(raw.slice(i,i+groupSize));
const sampled=groups.map(g=>({date:g[g.length-1].date,value:g.reduce((n,p)=>n+Number(p.revenue||0),0)}));
const values=sampled.map(p=>p.value),total=values.reduce((x,y)=>x+y,0),max=Math.max(1,...values),w=720,h=245,left=8,right=8,top=24,bottom=36;
const coords=sampled.map((p,i)=>({x:left+i/Math.max(1,sampled.length-1)*(w-left-right),y:top+(1-p.value/max)*(h-top-bottom)}));
const curve=coords.map((p,i)=>{if(!i)return 'M '+p.x+' '+p.y;const prev=coords[i-1],mid=(prev.x+p.x)/2;return ' C '+mid+' '+prev.y+' '+mid+' '+p.y+' '+p.x+' '+p.y}).join('');
const area=curve+' L '+coords[coords.length-1].x+' '+(h-bottom)+' L '+coords[0].x+' '+(h-bottom)+' Z';
const labels=sampled.map((p,i)=>({x:coords[i].x,text:p.date.toLocaleDateString('en-IE',{day:'numeric',month:'short'})}));
const hasRevenue=total>0;
const html=`<div class="tf-revenue-plot" data-chart-values="${esc(JSON.stringify(sampled.map((p,i)=>({x:coords[i].x,y:coords[i].y,value:p.value,date:p.date.toLocaleDateString('en-IE',{day:'numeric',month:'short'})}))))}"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="Interactive revenue chart. Drag to inspect recorded amounts."><defs><linearGradient id="tfHomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00e4ed" stop-opacity=".58"/><stop offset="1" stop-color="#00e4ed" stop-opacity=".02"/></linearGradient><filter id="tfHomeGlow"><feGaussianBlur stdDeviation="3" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>${[0,1,2,3].map(i=>`<line x1="8" x2="712" y1="${top+i*(h-top-bottom)/3}" y2="${top+i*(h-top-bottom)/3}" stroke="#3c7183" stroke-opacity=".22"/>`).join('')}<path d="${area}" fill="url(#tfHomeFill)"/><path d="${curve}" fill="none" stroke="#24f1f6" stroke-width="2.8" filter="url(#tfHomeGlow)"/><line class="tf-chart-crosshair" y1="${top}" y2="${h-bottom}" stroke="#3cf4fb" stroke-width="1.3" stroke-dasharray="6 5" visibility="hidden"/><circle class="tf-chart-dot" r="6" fill="#efffff" stroke="#23eaf1" stroke-width="3" visibility="hidden"/>${labels.filter((_,i)=>i===0||i===labels.length-1||period==='1W').map(p=>`<text x="${p.x}" y="${h-6}" text-anchor="${p.x<30?'start':p.x>680?'end':'middle'}" fill="#a2c0d0" font-size="13">${esc(p.text)}</text>`).join('')}</svg><div class="tf-chart-tooltip" hidden><strong></strong><small></small></div></div>`;
return {html,total,hasRevenue};
}
